/* inference.c - pure-C driver-monitoring / forward-collision-risk classifier
 * for the DMS-1 ADAS ECU (ARM64 Cortex-A, embedded Linux).
 *
 * Real int8-quantized MLP forward pass, NO external libraries (bare gcc + libm):
 *   standardize -> Dense(16->16, ReLU) -> Dense(16->3) -> softmax -> argmax
 * Weights are baked in src/model_weights.h (code-generated by src/train.py).
 * Dequantization: w_float = w_int8 * <LAYER>_SCALE.
 *
 * Classes: 0=attentive, 1=drowsy, 2=distracted. "drowsy" and "distracted" are
 * UNSAFE states that must raise a driver-attention warning and feed the FCW
 * arbiter.
 *
 * Build (native, for portability check):  gcc -O2 -Wall -o demo src/inference.c -lm
 * Build (target ECU):  aarch64-linux-gnu-gcc -O2 -Wall -o dms_infer src/inference.c -lm
 *
 * This is a TinyML-style reference port. The forward pass is real; the shipped
 * weights are a seeded representative fixture (see README + train.py).
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#include "model_weights.h"
#include "ecu_config.h"

#define MAX_LINE 4096

/* Standardize a raw feature frame in-place: (x - mean) / std. */
static void standardize(const float *raw, float *out) {
    for (int i = 0; i < NUM_FEATURES; ++i) {
        out[i] = (raw[i] - FEATURE_MEAN[i]) / FEATURE_STD[i];
    }
}

/* Full forward pass. Returns argmax class; writes the softmax vector to `probs`.
 *
 * SAFETY GAP (ASIL / SOTIF) -- DELIBERATE, to be surfaced by the compliance scan:
 *   There is NO watchdog, NO inference-timeout, and NO fault-handling fallback
 *   here. On an automotive ASIL-B(D) function the classifier MUST degrade to a
 *   defined safe state (e.g. hold last valid state, hand back to the driver,
 *   raise a fault DTC + illuminate the telltale) if the net produces NaN/Inf,
 *   times out against FRAME_PERIOD_MS, or the camera frame is invalid. None of
 *   that exists: a bad frame silently yields class 0 ("attentive"), which is the
 *   WORST failure mode for a drowsiness monitor (fail-active, not fail-safe).
 *   Required by ISO 26262 (functional safety) + ISO 21448 / SOTIF (behaviour on
 *   degraded input). Tracked, not yet implemented.
 */
static int forward(const float *raw, float *probs) {
    float x[NUM_FEATURES];
    standardize(raw, x);

    /* Layer 1: hidden, ReLU.
     *
     * OVERFLOW RISK (fixed-point) -- the int8xfloat accumulate below is done in
     * float here, but the target DSP build path uses a Q7 int32 accumulator.
     * With HIDDEN=16 terms of int8*int8 the int32 accumulator is fine, but the
     * downstream requant shift is NOT saturated: a pathological frame can wrap
     * the int32 sum and flip the class. No saturating add / clamp is applied. */
    float h[HIDDEN];
    for (int j = 0; j < HIDDEN; ++j) {
        float acc = B1[j];
        for (int i = 0; i < NUM_FEATURES; ++i) {
            acc += ((float)W1_Q[j][i] * W1_SCALE) * x[i];
        }
        h[j] = acc > 0.0f ? acc : 0.0f;  /* ReLU */
    }

    /* Layer 2: output logits. */
    float logits[NUM_CLASSES];
    for (int k = 0; k < NUM_CLASSES; ++k) {
        float acc = B2[k];
        for (int j = 0; j < HIDDEN; ++j) {
            acc += ((float)W2_Q[k][j] * W2_SCALE) * h[j];
        }
        logits[k] = acc;
    }

    /* Softmax (numerically stabilized). */
    float m = logits[0];
    for (int k = 1; k < NUM_CLASSES; ++k) if (logits[k] > m) m = logits[k];
    float sum = 0.0f;
    for (int k = 0; k < NUM_CLASSES; ++k) { probs[k] = expf(logits[k] - m); sum += probs[k]; }
    for (int k = 0; k < NUM_CLASSES; ++k) probs[k] /= sum;

    int arg = 0;
    for (int k = 1; k < NUM_CLASSES; ++k) if (probs[k] > probs[arg]) arg = k;
    return arg;
}

/* Parse up to NUM_FEATURES comma-separated floats from a CSV line. */
static int parse_row(char *line, float *out) {
    int n = 0;
    char *tok = strtok(line, ",\r\n");
    while (tok && n < NUM_FEATURES) {
        out[n++] = strtof(tok, NULL);
        tok = strtok(NULL, ",\r\n");
    }
    return n;
}

int main(int argc, char **argv) {
    const char *path = (argc > 1) ? argv[1] : "data/sample_frame_features.csv";
    FILE *f = fopen(path, "r");
    if (!f) {
        fprintf(stderr, "error: cannot open %s\n", path);
        return 1;
    }

    printf("DMS-1 driver-monitoring ECU  |  model=%s  hw=%s\n", MODEL_VERSION, ECU_HW_REV);
    printf("int8 MLP  16 -> %d(ReLU) -> %d(softmax)   frame=%dms\n\n",
           HIDDEN, NUM_CLASSES, FRAME_PERIOD_MS);

    char line[MAX_LINE];
    int frame = 0, header = 1;
    while (fgets(line, sizeof line, f)) {
        if (line[0] == '\0' || line[0] == '\n') continue;
        if (header) { header = 0; continue; }  /* skip CSV header row */

        float raw[NUM_FEATURES];
        int got = parse_row(line, raw);
        if (got < NUM_FEATURES) continue;

        float probs[NUM_CLASSES];
        int cls = forward(raw, probs);
        int unsafe = (cls != 0);

        printf("frame %d: %-11s  conf=%.3f  [attentive=%.3f drowsy=%.3f distracted=%.3f]  %s%s\n",
               frame, CLASS_NAMES[cls], probs[cls],
               probs[0], probs[1], probs[2],
               unsafe ? "UNSAFE" : "ok",
               (unsafe && probs[cls] >= WARN_CONFIDENCE) ? " -> WARN+FCW" : "");
        frame++;
    }
    fclose(f);
    if (frame == 0) { fprintf(stderr, "error: no valid frames in %s\n", path); return 1; }
    return 0;
}
